#!/usr/bin/env python3
"""CI/CD Pipeline Plugin - Build Artifact Deployer

This plugin handles deployment of build artifacts to target environments.
It supports custom pre/post deployment hooks defined in the project's
pipeline configuration file (.deploy.yml).
"""

import os
import subprocess
import yaml
import tempfile
import logging
from flask import Flask, request, jsonify
from functools import wraps

app = Flask(__name__)
logger = logging.getLogger(__name__)

DEPLOY_SERVICE_URL = os.environ.get('DEPLOY_SERVICE_URL', 'http://deploy-service.internal:8080')
ALLOWED_REGISTRIES = ['ecr.aws', 'gcr.io', 'docker.io']

def validate_token(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Pipeline-Token')
        if not token or len(token) < 32:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def sanitize_image_ref(image_ref):
    """Basic validation of container image reference format."""
    if not any(image_ref.startswith(r) for r in ALLOWED_REGISTRIES):
        raise ValueError(f"Registry not in allowlist: {image_ref}")
    if '..' in image_ref or image_ref.startswith('/'):
        raise ValueError(f"Invalid image reference: {image_ref}")
    return image_ref

def load_pipeline_config(repo_path):
    """Load deployment configuration from repository."""
    config_path = os.path.join(repo_path, '.deploy.yml')
    if not os.path.exists(config_path):
        return {}
    with open(config_path, 'r') as f:
        return yaml.safe_load(f)

def execute_hook(hook_command, env_vars=None):
    """Execute a deployment hook command.

    Hook commands are defined in the project's .deploy.yml and run
    in the context of the build agent.
    """
    merged_env = os.environ.copy()
    if env_vars:
        merged_env.update(env_vars)

    logger.info(f"Executing hook: {hook_command}")
    result = subprocess.run(
        hook_command,
        shell=True,
        capture_output=True,
        text=True,
        env=merged_env,
        timeout=300
    )
    return result.returncode, result.stdout, result.stderr

@app.route('/api/v1/deploy', methods=['POST'])
@validate_token
def trigger_deployment():
    """Trigger a deployment with optional pre/post hooks."""
    payload = request.get_json()
    if not payload:
        return jsonify({'error': 'invalid payload'}), 400

    repo_url = payload.get('repository_url', '')
    branch = payload.get('branch', 'main')
    image_ref = payload.get('image_ref', '')
    custom_hooks = payload.get('hooks', {})

    try:
        image_ref = sanitize_image_ref(image_ref)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    # Clone repo to get deployment config
    with tempfile.TemporaryDirectory() as tmpdir:
        clone_cmd = f"git clone --depth 1 --branch {branch} {repo_url} {tmpdir}/repo"
        ret, stdout, stderr = execute_hook(clone_cmd)
        if ret != 0:
            return jsonify({'error': 'clone failed', 'details': stderr}), 500

        config = load_pipeline_config(f"{tmpdir}/repo")

        # Execute pre-deploy hooks from config or request
        pre_hooks = custom_hooks.get('pre_deploy') or config.get('hooks', {}).get('pre_deploy', [])
        for hook in pre_hooks:
            hook_env = {'IMAGE_REF': image_ref, 'BRANCH': branch}
            ret, stdout, stderr = execute_hook(hook, env_vars=hook_env)
            if ret != 0:
                return jsonify({'error': f'pre-deploy hook failed: {hook}', 'stderr': stderr}), 500

        # Main deployment
        deploy_cmd = f"kubectl set image deployment/app app={image_ref} --record"
        ret, stdout, stderr = execute_hook(deploy_cmd)
        if ret != 0:
            return jsonify({'error': 'deployment failed', 'details': stderr}), 500

        # Post-deploy hooks
        post_hooks = custom_hooks.get('post_deploy') or config.get('hooks', {}).get('post_deploy', [])
        for hook in post_hooks:
            execute_hook(hook, env_vars={'IMAGE_REF': image_ref})

    return jsonify({'status': 'deployed', 'image': image_ref}), 200

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
